define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_26.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e151090","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_25.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e151194","topics":[]},{"title":"Applying LOTO - Cryocooler Compressor","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the cryocooler compressor breaker on the MDP when servicing this item. Applying LOTO ensures a safe environment when servicing the F50 cryocooler compressor.<\/p>","href":"t_Applying-LOTO-CryocoolerCompressor-Premier_3.html","attributes":{"data-id":"id_2001782"},"menu":{"hasChildren":false},"tocID":"id_2001782-d46e151298","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_21.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e151402","topics":[]},{"title":"Removing the F50 cryocooler compressor","shortdesc":"<p class=\"shortdesc\">Remove the F-50 cryocooler when replacement is required.<\/p>","href":"t_F50CryocoolerCompressorReplacement.html","attributes":{"data-id":"id_2001531"},"menu":{"hasChildren":false},"tocID":"id_2001531-d46e151506","topics":[]},{"title":"Install the replacement F50 cryocooler","href":"t_ReinstallingF50cryocooler.html","attributes":{"data-id":"id_2014722"},"menu":{"hasChildren":false},"tocID":"id_2014722-d46e151610","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_23.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e151711","topics":[]},{"title":"Removing LOTO - cryocooler compressor","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the cryocooler compressor breaker on the Main Disconnect Panel (MDP) before restoring cryocooler compressor power.<\/p>","href":"t_Removing-LOTO-CryocoolerCompressor-Premier_3.html","attributes":{"data-id":"id_2001784"},"menu":{"hasChildren":false},"tocID":"id_2001784-d46e151815","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_25.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e151919","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_44.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e152023","topics":[]}]});